content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #e0e7ff;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fee2e2;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --bg-page: #f3f4f6;
  --bg-card: #ffffff;
  --border-color: #e5e7eb;
  --border-focus: #818cf8;
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 25px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: linear-gradient(135deg, #e0e7ff 0%, #f3f4f6 50%, #ede9fe 100%);
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* レイアウト・カード */
.app-wrapper {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 32px 16px;
}

.app-card {
  width: 100%;
  max-width: 540px;
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ヘッダー */
.app-header {
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.025em;
  margin-bottom: 4px;
}

.app-subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* 進捗・ステータス */
.stats-container {
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stats-text {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.progress-bar-bg {
  width: 100%;
  height: 8px;
  background-color: #e2e8f0;
  border-radius: 9999px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #4f46e5 0%, #10b981 100%);
  border-radius: 9999px;
  transition: width 0.35s ease-in-out;
}

/* フォーム */
.form-container {
  display: flex;
  gap: 8px;
}

.todo-input {
  flex: 1;
  font-size: 0.95rem;
  padding: 10px 14px;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: #fafafa;
  color: var(--text-main);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s, background-color 0.2s;
}

.todo-input:focus {
  background-color: #ffffff;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.todo-input::placeholder {
  color: #9ca3af;
}

.add-button {
  background-color: var(--primary-color);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-md);
  padding: 10px 18px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.2s, transform 0.1s;
}

.add-button:hover {
  background-color: var(--primary-hover);
}

.add-button:active {
  transform: translateY(1px);
}

/* フィルター */
.filter-container {
  display: flex;
  gap: 6px;
  background-color: #f1f5f9;
  padding: 4px;
  border-radius: var(--radius-md);
}

.filter-button {
  flex: 1;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-button:hover {
  color: var(--text-main);
}

.filter-button-active {
  background-color: var(--bg-card);
  color: var(--primary-color);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* タスク一覧 */
.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 120px;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: #ffffff;
  gap: 12px;
  transition: border-color 0.2s, background-color 0.2s, box-shadow 0.2s;
}

.todo-item:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-sm);
}

.todo-item-completed {
  background-color: #f8fafc;
  border-color: #e2e8f0;
}

/* カスタムチェックボックス */
.checkbox-label {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  cursor: pointer;
  user-select: none;
  min-width: 0;
}

.checkbox-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.custom-checkbox {
  width: 20px;
  height: 20px;
  min-width: 20px;
  border: 2px solid #cbd5e1;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #ffffff;
  transition: all 0.2s;
}

.checkbox-label:hover .custom-checkbox {
  border-color: var(--primary-color);
}

.checkbox-input:focus-visible + .custom-checkbox {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.checkbox-input:checked + .custom-checkbox {
  background-color: var(--primary-color);
  border-color: var(--primary-color);
}

.checkbox-input:checked + .custom-checkbox::after {
  content: "";
  display: block;
  width: 5px;
  height: 9px;
  border: solid #ffffff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
  margin-bottom: 2px;
}

/* タスクテキスト */
.todo-text {
  font-size: 0.95rem;
  color: var(--text-main);
  word-break: break-word;
  transition: color 0.2s, text-decoration 0.2s;
}

.todo-item-completed .todo-text {
  text-decoration: line-through;
  color: #94a3b8;
}

/* 削除ボタン */
.delete-button {
  background: transparent;
  color: #94a3b8;
  border: none;
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  font-size: 0.85rem;
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.delete-button:hover {
  background-color: var(--danger-light);
  color: var(--danger-color);
}

/* 空状態 */
.empty-state {
  text-align: center;
  padding: 36px 16px;
  color: var(--text-muted);
  font-size: 0.95rem;
  background-color: #f8fafc;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
}

/* レスポンシブ対応 */
@media (max-width: 480px) {
  .app-wrapper {
    padding: 16px 8px;
  }

  .app-card {
    padding: 20px 16px;
    border-radius: 12px;
  }

  .app-title {
    font-size: 1.5rem;
  }

  .form-container {
    flex-direction: row;
  }

  .add-button {
    padding: 10px 14px;
    font-size: 0.9rem;
  }

  .filter-button {
    font-size: 0.8rem;
    padding: 6px 8px;
  }
}

export interface TodoItem {
  id: string;
  text: string;
  completed: boolean;
  createdAt: string;
}

export type FilterType = 'all' | 'active' | 'completed';

export interface FilterOption {
  value: FilterType;
  label: string;
}

export interface TodoFormProps {
  onAddTodo?: (text: string) => void;
}

export interface TodoListProps {
  todos?: TodoItem[];
  onToggleTodo?: (id: string) => void;
  onDeleteTodo?: (id: string) => void;
}

import { useState, type FormEvent, type ChangeEvent } from 'react';
import { TodoFormProps } from '../types';

const TodoForm = ({ onAddTodo }: TodoFormProps) => {
  const [inputText, setInputText] = useState('');

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const trimmed = inputText.trim();
    if (!trimmed) return;
    onAddTodo?.(trimmed);
    setInputText('');
  };

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
  };

  return (
    <form className="form-container" onSubmit={handleSubmit}>
      <input
        type="text"
        className="todo-input"
        placeholder="新しいやること・タスクを入力..."
        aria-label="新しいタスクを入力"
        maxLength={100}
        value={inputText}
        onChange={handleChange}
      />
      <button type="submit" className="add-button">
        追加
      </button>
    </form>
  );
};

export default TodoForm;

import { TodoListProps, FilterType } from '../types';

interface ComponentProps extends TodoListProps {
  filter?: FilterType;
}

const TodoList = ({
  todos = [],
  filter = 'all',
  onToggleTodo,
  onDeleteTodo,
}: ComponentProps) => {
  if (todos.length === 0) {
    const getEmptyMessage = () => {
      switch (filter) {
        case 'active':
          return '未完了のタスクはありません';
        case 'completed':
          return '完了済みのタスクはありません';
        case 'all':
        default:
          return 'タスクがまだ登録されていません';
      }
    };

    return (
      <div className="empty-state">
        {getEmptyMessage()}
      </div>
    );
  }

  return (
    <ul className="todo-list">
      {todos.map((todo) => {
        const itemClassName = todo.completed
          ? 'todo-item todo-item-completed'
          : 'todo-item';

        return (
          <li key={todo.id} className={itemClassName}>
            <label className="checkbox-label">
              <input
                type="checkbox"
                className="checkbox-input"
                checked={todo.completed}
                onChange={() => onToggleTodo?.(todo.id)}
              />
              <span className="custom-checkbox" />
              <span className="todo-text">{todo.text}</span>
            </label>
            <button
              type="button"
              className="delete-button"
              onClick={() => onDeleteTodo?.(todo.id)}
              aria-label={`「${todo.text}」を削除`}
            >
              削除
            </button>
          </li>
        );
      })}
    </ul>
  );
};

export default TodoList;

import { useState } from 'react';
import { TodoItem, FilterType, FilterOption } from './types';
import TodoForm from './components/TodoForm';
import TodoList from './components/TodoList';
import './index.css';

const INITIAL_TODOS: TodoItem[] = [
  {
    id: '1',
    text: '牛乳と卵の買い出しに行く',
    completed: true,
    createdAt: '2025-01-10T09:00:00.000Z',
  },
  {
    id: '2',
    text: '市役所に提出する申請書類を記入する',
    completed: false,
    createdAt: '2025-01-10T10:30:00.000Z',
  },
  {
    id: '3',
    text: 'リビングとキッチンの掃除機がけ',
    completed: true,
    createdAt: '2025-01-10T11:15:00.000Z',
  },
  {
    id: '4',
    text: '週末の旅行計画のホテルを予約する',
    completed: false,
    createdAt: '2025-01-10T14:00:00.000Z',
  },
  {
    id: '5',
    text: '図書館で借りた本を返却する',
    completed: false,
    createdAt: '2025-01-10T16:20:00.000Z',
  },
];

const FILTER_OPTIONS: FilterOption[] = [
  { value: 'all', label: 'すべて' },
  { value: 'active', label: '未完了' },
  { value: 'completed', label: '完了済み' },
];

const App = () => {
  const [todos, setTodos] = useState<TodoItem[]>(INITIAL_TODOS);
  const [filter, setFilter] = useState<FilterType>('all');

  const handleAddTodo = (text: string) => {
    const newTodo: TodoItem = {
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
      text,
      completed: false,
      createdAt: new Date().toISOString(),
    };
    setTodos((prev) => [newTodo, ...prev]);
  };

  const handleToggleTodo = (id: string) => {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDeleteTodo = (id: string) => {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  };

  const filteredTodos = todos.filter((todo) => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  });

  const totalCount = todos.length;
  const completedCount = todos.filter((todo) => todo.completed).length;
  const progressPercent = totalCount === 0 ? 0 : Math.round((completedCount / totalCount) * 100);

  return (
    <main className="app-wrapper">
      <div className="app-card">
        <header className="app-header">
          <h1 className="app-title">やることリスト</h1>
          <p className="app-subtitle">日々のタスクをすっきり整理・管理</p>
        </header>

        <section className="stats-container" aria-label="進捗状況">
          <div className="stats-text">
            <span>達成度 ({completedCount} / {totalCount} 完了)</span>
            <span>{progressPercent}%</span>
          </div>
          <div
            className="progress-bar-bg"
            role="progressbar"
            aria-valuenow={progressPercent}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-label="タスク達成度"
          >
            <div
              className="progress-bar-fill"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
        </section>

        <TodoForm onAddTodo={handleAddTodo} />

        <nav className="filter-container" aria-label="タスクの絞り込み">
          {FILTER_OPTIONS.map((option) => (
            <button
              key={option.value}
              type="button"
              className={filter === option.value ? 'filter-button filter-button-active' : 'filter-button'}
              onClick={() => setFilter(option.value)}
            >
              {option.label}
            </button>
          ))}
        </nav>

        <TodoList
          todos={filteredTodos}
          onToggleTodo={handleToggleTodo}
          onDeleteTodo={handleDeleteTodo}
        />
      </div>
    </main>
  );
};

export default App;
